from swat_toolkit.io.readers import  ReadFileLinefrom swat_toolkit.io.MappingSWATFile import  SWATFileMappingfrom pathlib import Pathclass TxInOut(ReadFileLine, SWATFileMapping):    def __init__(self, txtinout_dir):        super().__init__()        self.directory = Path(txtinout_dir)        self.hru_info = self.__extract_hru()        self.number_hru, self.number_sub = self.__count_hru()    def __repr__(self):        return f"FOLDER TxtInOut: {self.directory!r})"    #________________________________________________________    def get_resevoir(self, ext: str, reservoir_id: int):        return self.directory / SWATFileMapping._get_reservoir_file(ext, reservoir_id)    def get_output_file(self, ext: str):        return self.directory / SWATFileMapping._get_output_file(ext)    def get_watershed_file(self, ext: str):        return self.directory / SWATFileMapping._get_watershed_file(ext)    def get_weather_file(self, ext: str, index: int = 1):        return self.directory / SWATFileMapping._get_indexed_file(ext, index)    #________________________________________________________    def __count_hru(self):        hru_ids = {row['HRU'] for row in self.hru_info}        sub_ids = {row['Subbasin'] for row in self.hru_info}        return len(hru_ids), len(sub_ids)    def __extract_hru(self):        hru_infos = []        for file in self.find_files_ext(".hru"):            line = self._read_file(file, first_line=True)            att = self._read_hru_attribute(line)            att = {"name": Path(file).stem, **att}            hru_infos.append(att)        return hru_infosif __name__ == "__main__":    # __import__('doctest').testmod()    txinout = TxInOut(            r"D:\ArcSWAT\SWAT\ht_ThanhSon\Scenarios\ht_thanhson\TxtInOut")    # print(txinout.hru_info)    print(txinout.find_files_name('10001'))